    {tab === 'mail' && <>{data.map((mail: any) => <details key={mail.id}><summary>{mail.subject} · {mail.recipient} · {stateLabel(mail.status, t)}</summary><CustomerSummary record={mail}/><AdminMailPreview mail={mail}/><button onClick={() => { const match = mail.html.match(/href="([^"]*\/(?:recover|account)#(?:token|verify|reset)=[^"]+)"/); if (match)
            location.assign(match[1]); }}>{t.confirm}</button></details>)}</>}
